const raw = '{"name":"Ada","score":95}';

const unsafe: any = JSON.parse(raw);
console.log(unsafe.name.toUpperCase()); // compiles — may crash

const safe: unknown = JSON.parse(raw);
// safe.name;                        // compile error
if (typeof safe === "object" && safe !== null && "name" in safe) {
  const name = (safe as { name: string }).name;
  console.log(name.toUpperCase());
}

function printLength(value: unknown): void {
  if (typeof value === "string") {
    console.log(value.length);     // value is string here
  } else if (typeof value === "number") {
    console.log(value.toFixed(2)); // value is number here
  } else {
    console.log("unsupported type");
  }
}

function assertNever(value: never, msg = "Unexpected value"): never {
  throw new Error(`${msg}: ${JSON.stringify(value)}`);
}

type Status = "pending" | "done";

function handle(status: Status): string {
  switch (status) {
    case "pending": return "wait";
    case "done": return "ok";
    default: return assertNever(status);
  }
}

function parseConfig(raw: string): any {
  return JSON.parse(raw);
}

function getTimeout(config: { timeout: number }): number {
  return config.timeout;
}

// any poisons the chain — no error:
const cfg = parseConfig("{}");
getTimeout(cfg);  // compiles, crashes at run time
